// Lesson: Parallel Swarm Networks (phase 16 / lesson 09)
// Go port of code/main.py. Go standard library only.
// Source: phases/16-multi-agent-and-swarms/09-parallel-swarm-networks/docs/en.md
// Run: go run code/main.go

package main

import (
	"fmt"
	"math"
	"strings"
	"sync"
	"time"
)

type Task struct {
	TaskID      int
	Duration    float64
	PreAssigned int
}

func fakeWork(task Task) string {
	time.Sleep(time.Duration(task.Duration * float64(time.Second)))
	return fmt.Sprintf("task-%d-done", task.TaskID)
}

func pyCounts(counts []int) string {
	parts := make([]string, len(counts))
	for i, c := range counts {
		parts[i] = fmt.Sprintf("%d: %d", i, c)
	}
	return "{" + strings.Join(parts, ", ") + "}"
}

func runSequential(tasks []Task) (float64, []int) {
	t0 := time.Now()
	counts := []int{0}
	for _, t := range tasks {
		fakeWork(t)
		counts[0]++
	}
	return time.Since(t0).Seconds(), counts
}

func runFixedAssignment(tasks []Task, nWorkers int) (float64, []int) {
	perWorker := make([][]Task, nWorkers)
	for _, t := range tasks {
		perWorker[t.PreAssigned] = append(perWorker[t.PreAssigned], t)
	}
	counts := make([]int, nWorkers)

	t0 := time.Now()
	var wg sync.WaitGroup
	for wid := 0; wid < nWorkers; wid++ {
		wg.Add(1)
		go func(wid int) {
			defer wg.Done()
			for _, t := range perWorker[wid] {
				fakeWork(t)
				counts[wid]++
			}
		}(wid)
	}
	wg.Wait()
	return time.Since(t0).Seconds(), counts
}

func runSwarm(tasks []Task, nWorkers int) (float64, []int) {
	q := make(chan Task, len(tasks))
	for _, t := range tasks {
		q <- t
	}
	close(q)
	counts := make([]int, nWorkers)
	var mu sync.Mutex

	t0 := time.Now()
	var wg sync.WaitGroup
	for wid := 0; wid < nWorkers; wid++ {
		wg.Add(1)
		go func(wid int) {
			defer wg.Done()
			for task := range q {
				fakeWork(task)
				mu.Lock()
				counts[wid]++
				mu.Unlock()
			}
		}(wid)
	}
	wg.Wait()
	return time.Since(t0).Seconds(), counts
}

func makeTasks(nWorkers int) []Task {
	tasks := []Task{}
	for i := 0; i < 8; i++ {
		isSlow := i < 4
		duration := 0.1
		pre := ((i-3)%nWorkers + nWorkers) % nWorkers
		if isSlow {
			duration = 0.4
			pre = 0
		}
		tasks = append(tasks, Task{TaskID: i, Duration: duration, PreAssigned: pre})
	}
	return tasks
}

func main() {
	fmt.Println("Swarm architecture demo: variable-duration workload")
	fmt.Println(strings.Repeat("-", 56))
	nWorkers := 4

	tasks := makeTasks(nWorkers)
	totalWork := 0.0
	for _, t := range tasks {
		totalWork += t.Duration
	}
	fmt.Printf("%d tasks, 4 slow (0.4s) + 4 fast (0.1s)\n", len(tasks))
	fmt.Printf("Total work-seconds: %.2fs\n", totalWork)
	fmt.Printf("Ideal parallel time with %d workers: %.2fs\n", nWorkers, totalWork/float64(nWorkers))

	seqTime, seqCounts := runSequential(tasks)
	fmt.Printf("\nSequential (1 worker):      wall=%.2fs, counts=%s\n", seqTime, pyCounts(seqCounts))

	fixedTime, fixedCounts := runFixedAssignment(tasks, nWorkers)
	fmt.Printf("Fixed assignment (%d workers): wall=%.2fs, counts=%s\n", nWorkers, fixedTime, pyCounts(fixedCounts))
	fmt.Println("  worker 0 got all 4 slow tasks; other workers idle after their fast ones.")

	swarmTime, swarmCounts := runSwarm(tasks, nWorkers)
	fmt.Printf("Swarm (%d workers):            wall=%.2fs, counts=%s\n", nWorkers, swarmTime, pyCounts(swarmCounts))
	fmt.Println("  load balances automatically: slow workers finish first, fast pull next job.")

	speedupVsSeq := math.Inf(1)
	speedupVsFixed := math.Inf(1)
	if swarmTime > 0 {
		speedupVsSeq = seqTime / swarmTime
		speedupVsFixed = fixedTime / swarmTime
	}
	fmt.Printf("\nSwarm speedup vs sequential: %.2fx\n", speedupVsSeq)
	fmt.Printf("Swarm speedup vs fixed:      %.2fx\n", speedupVsFixed)
	fmt.Println("\nTakeaway: swarm wins when duration varies and assignment is hard to predict.")
	fmt.Println("Tradeoff: no central trace; debugging requires per-task IDs and durable logs.")
}

// Lesson: Parallel / Swarm / Networked Architectures (phase 16 / lesson 09)
// TypeScript port of code/main.py. Node standard library only.
// Source: phases/16-multi-agent-and-swarms/09-parallel-swarm-networks/docs/en.md
// Run: npx tsx phases/16-multi-agent-and-swarms/09-parallel-swarm-networks/code/main.ts

import { setTimeout as sleep } from "node:timers/promises";

interface Task {
  task_id: number;
  duration: number;
  pre_assigned: number;
}

type Counts = Map<number, number>;

function now(): number {
  return performance.now() / 1000;
}

function pyCounts(c: Counts): string {
  return "{" + [...c.entries()].map(([k, v]) => `${k}: ${v}`).join(", ") + "}";
}

async function fakeWork(task: Task): Promise<string> {
  await sleep(task.duration * 1000);
  return `task-${task.task_id}-done`;
}

async function runSequential(tasks: Task[]): Promise<[number, Counts]> {
  const t0 = now();
  const counts: Counts = new Map([[0, 0]]);
  for (const t of tasks) {
    await fakeWork(t);
    counts.set(0, counts.get(0)! + 1);
  }
  return [now() - t0, counts];
}

async function runFixedAssignment(tasks: Task[], nWorkers: number): Promise<[number, Counts]> {
  const perWorker = new Map<number, Task[]>();
  for (let i = 0; i < nWorkers; i++) perWorker.set(i, []);
  for (const t of tasks) perWorker.get(t.pre_assigned)!.push(t);
  const counts: Counts = new Map();
  for (let i = 0; i < nWorkers; i++) counts.set(i, 0);

  const worker = async (wid: number): Promise<void> => {
    for (const t of perWorker.get(wid)!) {
      await fakeWork(t);
      counts.set(wid, counts.get(wid)! + 1);
    }
  };

  const t0 = now();
  const workers: Promise<void>[] = [];
  for (let i = 0; i < nWorkers; i++) workers.push(worker(i));
  await Promise.all(workers);
  return [now() - t0, counts];
}

async function runSwarm(tasks: Task[], nWorkers: number): Promise<[number, Counts]> {
  const q: Task[] = [...tasks];
  const counts: Counts = new Map();
  for (let i = 0; i < nWorkers; i++) counts.set(i, 0);

  const worker = async (wid: number): Promise<void> => {
    while (true) {
      const task = q.shift();
      if (task === undefined) return;
      await fakeWork(task);
      counts.set(wid, counts.get(wid)! + 1);
    }
  };

  const t0 = now();
  const workers: Promise<void>[] = [];
  for (let i = 0; i < nWorkers; i++) workers.push(worker(i));
  await Promise.all(workers);
  return [now() - t0, counts];
}

function makeTasks(nWorkers = 4): Task[] {
  const tasks: Task[] = [];
  for (let i = 0; i < 8; i++) {
    const isSlow = i < 4;
    tasks.push({
      task_id: i,
      duration: isSlow ? 0.4 : 0.1,
      pre_assigned: isSlow ? 0 : (((i - 3) % nWorkers) + nWorkers) % nWorkers,
    });
  }
  return tasks;
}

async function main(): Promise<void> {
  console.log("Swarm architecture demo: variable-duration workload");
  console.log("-".repeat(56));
  const nWorkers = 4;

  const tasks = makeTasks(nWorkers);
  const totalWork = tasks.reduce((s, t) => s + t.duration, 0);
  console.log(`${tasks.length} tasks, 4 slow (0.4s) + 4 fast (0.1s)`);
  console.log(`Total work-seconds: ${totalWork.toFixed(2)}s`);
  console.log(`Ideal parallel time with ${nWorkers} workers: ${(totalWork / nWorkers).toFixed(2)}s`);

  const [seqTime, seqCounts] = await runSequential(tasks);
  console.log(`\nSequential (1 worker):      wall=${seqTime.toFixed(2)}s, counts=${pyCounts(seqCounts)}`);

  const [fixedTime, fixedCounts] = await runFixedAssignment(tasks, nWorkers);
  console.log(`Fixed assignment (${nWorkers} workers): wall=${fixedTime.toFixed(2)}s, counts=${pyCounts(fixedCounts)}`);
  console.log("  worker 0 got all 4 slow tasks; other workers idle after their fast ones.");

  const [swarmTime, swarmCounts] = await runSwarm(tasks, nWorkers);
  console.log(`Swarm (${nWorkers} workers):            wall=${swarmTime.toFixed(2)}s, counts=${pyCounts(swarmCounts)}`);
  console.log("  load balances automatically: slow workers finish first, fast pull next job.");

  const speedupVsSeq = swarmTime > 0 ? seqTime / swarmTime : Infinity;
  const speedupVsFixed = swarmTime > 0 ? fixedTime / swarmTime : Infinity;
  console.log(`\nSwarm speedup vs sequential: ${speedupVsSeq.toFixed(2)}x`);
  console.log(`Swarm speedup vs fixed:      ${speedupVsFixed.toFixed(2)}x`);
  console.log("\nTakeaway: swarm wins when duration varies and assignment is hard to predict.");
  console.log("Tradeoff: no central trace; debugging requires per-task IDs and durable logs.");
}

main();
